mapper.sql:
FROM nw_institution_integrations i LEFT JOIN nw_external_institution_mappings m ON m.tenant_id=i.tenant_id AND m.integration_id=i.integration_id
WHERE i.tenant_id=#{tenant}
AND i.integration_id=#{id}
AND (#{query}='' OR strpos(lower(i.integration_id),lower(#{query}))>0 OR strpos(lower(coalesce(m.namespace,'')),lower(#{query}))>0 OR strpos(lower(coalesce(m.external_institution_ref,'')),lower(#{query}))>0)
